184	    switch (schema.getType()) {
185	      case INT32:
186	        generateINT32(obj, row);
187	        break;
188	      case DATE:
189	        generateDATE(obj, row);
190	        break;
191	      case INT64:
192	      case TIMESTAMP:
193	        generateINT64(obj, row);
194	        break;
195	      case FLOAT:
196	        generateFLOAT(obj, row);
197	        break;
198	      case DOUBLE:
199	        generateDOUBLE(obj, row);
200	        break;
201	      case BOOLEAN:
202	        generateBOOLEAN(obj, row);
203	        break;
204	      case TEXT:
205	      case BLOB:
206	      case STRING:
207	        generateTEXT(obj, row);
208	        break;
209	      default:
210	        LOGGER.error("Wrong data type {}.", schema.getType());
211	    }
212	  }
