50	  public TsFileInsertionEventTableParser(
51	      final File tsFile,
52	      final TablePattern pattern,
53	      final long startTime,
54	      final long endTime,
55	      final PipeTaskMeta pipeTaskMeta,
56	      final PipeInsertionEvent sourceEvent)
57	      throws IOException {
58	    super(null, pattern, startTime, endTime, pipeTaskMeta, sourceEvent);
59	
60	    try {
61	      tsFileSequenceReader = new TsFileSequenceReader(tsFile.getPath(), true, true);
62	      filteredTableSchemaIterator =
63	          tsFileSequenceReader.readFileMetadata().getTableSchemaMap().entrySet().stream()
64	              .filter(entry -> Objects.isNull(pattern) || pattern.matchesTable(entry.getKey()))
65	              .iterator();
66	      tableQueryExecutor =
67	          new TableQueryExecutor(
68	              new MetadataQuerierByFileImpl(tsFileSequenceReader),
69	              new CachedChunkLoaderImpl(tsFileSequenceReader),
70	              TableQueryExecutor.TableQueryOrdering.DEVICE);
