32	import org.apache.tsfile.write.schema.IMeasurementSchema;
33	
34	import java.io.IOException;
35	import java.util.ArrayList;
36	import java.util.Iterator;
37	import java.util.List;
38	import java.util.NoSuchElementException;
39	
40	import static org.apache.tsfile.enums.TSDataType.DATE;
41	
42	public class TsFileInsertionEventTableParserTabletIterator implements Iterator<Tablet> {
43	
44	  private final String tableName;
45	
46	  private final long startTime;
47	  private final long endTime;
48	
49	  private final List<IMeasurementSchema> columnSchemas;
50	  private final List<Tablet.ColumnCategory> columnTypes;
51	  private final List<String> columnNames;
52	  private final TsBlockReader tsBlockReader;
53	
54	  public TsFileInsertionEventTableParserTabletIterator(
55	      final TableQueryExecutor tableQueryExecutor,
56	      final String tableName,
57	      final TableSchema tableSchema,
58	      final long startTime,
59	      final long endTime) {
60	    this.tableName = tableName;
61	    this.startTime = startTime;
62	    this.endTime = endTime;
63	
64	    columnSchemas = new ArrayList<>();
65	    columnTypes = new ArrayList<>();
66	    columnNames = new ArrayList<>();
67	    try {
68	      for (int i = 0, size = tableSchema.getColumnSchemas().size(); i < size; i++) {
69	        final IMeasurementSchema schema = tableSchema.getColumnSchemas().get(i);
70	        if (schema.getMeasurementName() != null && !schema.getMeasurementName().isEmpty()) {
71	          columnSchemas.add(schema);
72	          columnTypes.add(tableSchema.getColumnTypes().get(i));
73	          columnNames.add(schema.getMeasurementName());
74	        }
75	      }
76	
77	      tsBlockReader = tableQueryExecutor.query(tableName, columnNames, null, null, null);
78	    } catch (final ReadProcessException e) {
79	      throw new PipeException("Failed to build query data set", e);
80	    }
81	  }
82	
83	  @Override
84	  public boolean hasNext() {
85	    return tsBlockReader.hasNext();
86	  }
87	
88	  @Override
89	  public Tablet next() {
90	    if (!hasNext()) {
91	      throw new NoSuchElementException();
92	    }
93	
94	    try {
95	      return buildNextTablet();
96	    } catch (final IOException e) {
97	      throw new PipeException("Failed to build tablet", e);
98	    }
99	  }
100	
101	  // TODO: memory control
102	  private Tablet buildNextTablet() throws IOException {
103	    final TsBlock tsBlock = tsBlockReader.next();
104	
105	    List<String> measurementList = new ArrayList<>(columnSchemas.size());
106	    List<TSDataType> dataTypeList = new ArrayList<>(columnSchemas.size());
107	    columnSchemas.forEach(
108	        columnSchema -> {
109	          measurementList.add(columnSchema.getMeasurementName());
110	          dataTypeList.add(columnSchema.getType());
111	        });
112	    final Tablet tablet =
113	        new Tablet(
114	            tableName, measurementList, dataTypeList, columnTypes, tsBlock.getPositionCount());
115	    tablet.initBitMaps();
116	
117	    boolean isAllNull = true;
118	
119	    final TsBlock.TsBlockRowIterator rowIterator = tsBlock.getTsBlockRowIterator();
120	    while (rowIterator.hasNext()) {
121	      final Object[] row = rowIterator.next();
122	
123	      final long timestamp = (Long) row[row.length - 1];
124	      if (timestamp < startTime || timestamp > endTime) {
125	        continue;
126	      }
127	
128	      final int rowIndex = tablet.getRowSize();
129	      tablet.addTimestamp(rowIndex, timestamp);
130	      for (int i = 0, fieldSize = row.length - 1; i < fieldSize; i++) {
131	        final Object value =
132	            columnSchemas.get(i).getType() != DATE || row[i] == null
133	                ? row[i]
134	                : DateUtils.parseIntToLocalDate((Integer) row[i]);
135	        tablet.addValue(columnNames.get(i), rowIndex, value);
136	        if (value != null && columnTypes.get(i) == Tablet.ColumnCategory.FIELD) {
137	          isAllNull = false;
138	        }
139	      }
140	    }
141	
142	    if (isAllNull) {
143	      tablet.setRowSize(0);
144	    }
145	
146	    return tablet;
147	  }
148	}
